require_once __DIR__.'/../../../app/bootstrap.php';require_once __DIR__.'/../../../app/Modules/Marketplace/Marketplace.php';Auth::requireRole(['super_admin','owner']);$db=Database::connect();marketplace_install($db);$pageTitle='Homepage Marketplace';$err='';
function mp15_banner_upload(array $f,string $tag):?string{if(empty($f['name'])||empty($f['tmp_name']))return null;if(($f['error']??0)!==UPLOAD_ERR_OK)throw new RuntimeException('Upload banner gagal.');if(($f['size']??0)>6*1024*1024)throw new RuntimeException('Banner maksimal 6MB.');$info=@getimagesize($f['tmp_name']);$ext=[IMAGETYPE_JPEG=>'jpg',IMAGETYPE_PNG=>'png',IMAGETYPE_WEBP=>'webp'][$info[2]??0]??null;if(!$ext)throw new RuntimeException('Banner harus JPG/PNG/WEBP.');$dir=__DIR__.'/../../uploads/storefront/banners';if(!is_dir($dir))mkdir($dir,0775,true);$n='banner-'.$tag.'-'.date('YmdHis').'-'.bin2hex(random_bytes(3)).'.'.$ext;if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$n))throw new RuntimeException('Banner gagal disimpan.');return 'uploads/storefront/banners/'.$n;}
