e,image_desktop,image_mobile,link_url,position,is_active,sort_order,starts_at,ends_at,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,NOW())")->execute([$title,$sub?:null,$desk,$mobile,$link?:null,$position,$active,$sort,$starts,$ends]);$id=(int)$db->lastInsertId();}marketplace_v15_log($db,'banner.save','banner',$id,$title);flash('success','Banner disimpan.');legacy_redirect('admin/marketplace-homepage/index.php');}catch(Throwable $e){$err=$e->getMessage();}}
$edit=null;if(isset($_GET['edit'])){$s=$db->prepare("SELECT * FROM marketplace_banners WHERE id=?");$s->execute([(int)$_GET['edit']]);$edit=$s->fetch()?:null;}$rows=$db->query("SELECT * FROM marketplace_banners ORDER BY position,sort_order,id DESC")->fetchAll()?:[];$ok=flash('success');require __DIR__.'/../../layouts/admin-header.php';require __DIR__.'/../../layouts/admin-sidebar.php';?>
<link rel="stylesheet" href="<?=legacy_base_url('assets/css/marketplace-customer-admin.css?v=15')?>"><main class="admin-main mp-admin"><header class="admin-topbar page-topbar"><button class="sidebar-toggle" id="sidebarToggle"><i class="bi bi-list"></i></button><div class="topbar-title"><h1>Homepage Builder</h1><p>Atur section dan banner marketplace tanpa mengubah tema POS.</p></div></header><?php if($ok):?><div class="mp-alert success"><?=e($ok)?></div><?php endif;?><?php if($err):?><div class="mp-alert error"><?=e($err)?></div><?php endif;?><section class="mp-panel"><div class="mp-panel-head"><h3>Section Homepage</h3></div><form method="post" class="mp-toggle-grid"><?=CSRF::input()?><input type="hidden" name="action" value="settings"><?php foreach(['marketplace_home_show_banners'=>'Banner/Slider','marketplace_home_show_flash'=>'Flash Sale','marketplace_home_show_brands'=>'Brand Pilihan','marketplace_home_show_latest'=>'Produk Terbaru'] as $k=>$l):?><label class="mp-check"><input type="checkbox" name="<?=$k?>" <?=setting($k,'on')==='on'?'checked':''?>> <?=$l?></label><?php endforeach;?><button class="mp-btn">Simpan Section</button></form></section><section class="mp-admin-grid two"><section class="mp-panel"><div class="mp-panel-head"><h3><?=$edit?'Edit Banner':'Banner Baru'?></h3></div><form method="post" enctype="multipart/form-data" class="mp-form"><?=CSRF::input()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><label>Judul<input name="title" required value="<?=e($edit['title']??'')?>"></label><label>Subjudul<input name="subtitle" value="<?=e($edit['subtitle']??'')?>"></label><label>Posisi<select name="position"><option value="hero" <?=($edit['position']??'')==='hero'?'selected':''?>>Hero</option><option value="promo" <?=($edit['position']??'')==='promo'?'selected':''?>>Promo</option><option value="custom" <?=($edit['position']??'')==='custom'?'selected':''?>>Custom</option></select></label><label>URL Tujuan<input name="link_url" value="<?=e($edit['link_url']??'')?>" placeholder="produk/12-nama atau https://..."></label><label>Banner Desktop<input type="file" name="image_desktop" accept="image/*"></label><label>Banner Mobile<input type="file" name="image_mobile" accept="image/*"></label><label>Mulai<input type="datetime-local" name="starts_at" value="<?=!empty($edit['starts_at'])?e(date('Y-m-d\TH:i',strtotime($edit['starts_at']))):''?>"></label><label>Selesai<input type="datetime-local" name="ends_at" value="<?=!empty($edit['ends_at'])?e(date('Y-m-d\TH:i',strtotime($edit['ends_at']))):''?>"></label><label>Urutan<input type="number" name="sort_order" value="<?=e($edit['sort_order']??0)?>"></label><label class="mp-check"><input type="checkbox" name="is_active" <?=$edit&&!$edit['is_active']?'':'checked'?>> Aktif</label><button class="mp-btn"><i class="bi bi-save"></i> Simpan Banner</button></form></section><section class="mp-panel"><div class="mp-panel-head"><h3>Banner Aktif/Arsip</h3></div><div class="table-premium-card"><table class="premium-table"><thead><tr><th>Judul</th><th>Posisi</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['title'])?></b><br><small><?=e($r['link_url']?:'-')?></small></td><td><?=e($r['position'])?></td><td><?=$r['is_active']?'Aktif':'Off'?></td><td><a class="mp-icon" href="?edit=<?=$r['id']?>"><i class="bi bi-pencil"></i></a><form method="post" style="display:inline" onsubmit="return confirm('Hapus banner?')"><?=CSRF::input()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="mp-icon danger"><i class="bi bi-trash"></i></button></form></td></tr><?php endforeach;?></tbody></table></div></section></section></main><?php require __DIR__.'/../../layouts/admin-footer.php';?>
